sys_script_include.script:
var FeedbackUtils = Class.create();
FeedbackUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	createFeedback: function() {
		var feedbackID = this.getParameter('sysparam_feedbackID');
        var rating = this.getParameter('sysparm_rating');
        var comments = this.getParameter('sysparm_comments');
        var eventID = this.getParameter('sysparm_eventID');
        var attendeeID = this.getParameter('sysparm_attendeeID');


        var feedbackGR = new GlideRecord('x_1610434_event_0_feedback'); 
        feedbackGR.addQuery('sys_id',feedbackID);
		feedbackGR.query();
		while(feedbackGR.next()){
        feedbackGR.setValue('rating', rating);
        feedbackGR.setValue('comment', comments);
        feedbackGR.setValue('event_id', eventID);
        feedbackGR.setValue('attendee_id', attendeeID);
		feedbackGR.update();
		}
        return 'success';
    },

    type: 'FeedbackUtils'
});
